;{  char *mes = (0 < n && n < sys_nerr ? sys_errlist[n] : undoc);  if (mes != undoc)    return mes;  else    {      static char message [32];      sprintf (message, "Error #%03d:%03d", n >> 8, n & 0xff);      return message;    }}void perror (s)     char *s;{  if (s)    fprintf (stderr, "%s:", s);  fprintf (stderr, " %s\n", strerror (errno));}